// Afzender. Eén plek om te wisselen als iemand anders de batch verstuurt.
const SENDER = 'Luuk';

// Afmeldregel, voor AVG-dekking bij koude B2B-mail. Leeg op verzoek;
// zet de tekst terug om hem weer mee te sturen.
const OPT_OUT = '';

const row = $json;
// Haal een achterliggende haakjes-toevoeging weg, zodat er niet
// "Hoi MOO Print Limited (UK)," staat.
const business = (String(row['Business'] ?? '').replace(/\s*\([^)]*\)\s*$/, '').trim()
                  || String(row['Business'] ?? '').trim() || 'daar');
const venue = String(row['Nearest FC Urban venue'] ?? '').trim();
const city  = String(row['City'] ?? '').trim() || 'jullie stad';
const walk  = Number(row['Walk (min)']);

// WhatsApp komt alleen aan op mobiele nummers. Ongeveer 90% van deze sheet is
// vast, dus de meeste rijen geven hier '' terug en gaan via de IF-node langs
// de WhatsApp-tak heen.
function mobileE164(raw) {
  const d = String(raw ?? '').replace(/[^\d+]/g, '');
  if (!d.startsWith('+')) return '';
  const n = d.slice(1);
  const isMobile =
       /^447\d{9}$/.test(n)        // UK
    || /^316\d{8}$/.test(n)        // NL
    || /^467\d{8}$/.test(n)        // SE
    || /^491[5-7]\d{7,9}$/.test(n) // DE
    || /^34[67]\d{8}$/.test(n)     // ES
    || /^324\d{8}$/.test(n);       // BE
  return isMobile ? n : '';
}
const waTo = mobileE164(row['Phone (international)']);

// Bedrijfsnamen bevatten & en af en toe een aanhalingsteken - escapen voordat
// ze in de HTML terechtkomen.
const esc = (t) => String(t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const link = (text, url) => url ? `<a href="${esc(url)}">${esc(text)}</a>` : esc(text);

// Claim alleen een afstand die de sheet echt geeft.
let proximity;
if (venue && Number.isFinite(walk) && walk > 0) {
  const min = walk === 1 ? 'minuut' : 'minuten';
  proximity = `We hebben velden beschikbaar bij ${esc(venue)}, ongeveer ${walk} ${min} lopen van jullie kantoor.`;
} else if (venue) {
  proximity = `We hebben velden beschikbaar bij ${esc(venue)}, vlak bij jullie kantoor.`;
} else {
  proximity = `We hebben velden beschikbaar in ${esc(city)}.`;
}

const venueSlug = VENUE_SLUGS[venue];
const venueLink = venue ? link(venue, venueSlug ? VENUE_BASE + venueSlug : '') : esc(city);
const closing = `Je vindt meer informatie over ${link('FC Urban', FC_URBAN_URL)}`
              + ` en over onze locatie ${venueLink}.`;

const subject = `Na werktijd voetballen met het team van ${business}`;

const paras = [
  `Hi ${esc(business)},`,

  `Ik ben ${SENDER} van FC Urban. Wij organiseren voetbalwedstrijden in ${esc(city)} waar je `
  + `gewoon kunt aansluiten en meespelen. Daarnaast organiseren we ook specifiek wedstrijden `
  + `voor bedrijven.`,

  proximity,

  `We zijn op zoek naar iemand binnen ${esc(business)} die het leuk zou vinden om te helpen `
  + `een vast voetbalmoment na werktijd op te zetten voor collega’s.`,

  `FC Urban regelt het veld, vult de groep aan met spelers als dat nodig is, en de organisatie. `
  + `We hebben vooral iemand intern nodig die van voetbal houdt en collega’s enthousiast kan maken.`,

  `Zou je me in contact kunnen brengen met degene die zich bezighoudt met vitaliteit, HR of `
  + `personeelsuitjes in ${esc(city)}? Of een persoon waarvan je weet dat die dit graag wil `
  + `opzetten? Alvast bedankt!`,

  closing,

  `Groet,<br>${SENDER}<br>FC Urban`,
];
if (OPT_OUT) paras.push(`<span style="color:#888;font-size:12px">${esc(OPT_OUT)}</span>`);

const html = paras.map((p) => `<p>${p}</p>`).join('\n');

return { json: { ...row, to: row._to, waTo, waName: business, waVenue: venue || city, subject, html } };

